CREATE   VIEW [synapse_ce].[vwQuoteDetail]
AS
SELECT 
	qd.[quotedetailid],
	qd.[quotedetailname],
	qd.[quoteid],
	qd.[quotestatecode],
	qd.[createdon],
	qd.[createdby],
	qd.[modifiedon],
	qd.[modifiedby],
	qd.[ownerid],
	qd.[productid],
	qd.[productname],
	qd.[msdyn_linedescription], 
	qd.[productnumber],
	qd.[producttypecode],
	prdtypecode.[LocalizedLabel] AS [ProductTypeCode_Description],
	qd.[msdyn_includefee],
	qd.[transactioncurrencyid],
	cur.[currencyname],
	cur.[isocurrencycode] AS [CurrencyCode],
	qd.[priceperunit_base],
	qd.[msdyn_costpriceperunit],
	qd.[msdyn_costpriceperunit_base],
	qd.[extendedamount],
	qd.[extendedamount_base],
	qd.[baseamount],
	qd.[baseamount_base],
	qd.[tax],
	qd.[tax_base],
	qd.[manualdiscountamount],
	qd.[manualdiscountamount_base],
	qd.[msdyn_estimatedrevenue],
	qd.[msdyn_estimatedrevenue_base],
	qd.[msdyn_estimatedcost],
	qd.[msdyn_estimatedcost_base],
	qd.[msdyn_estimatedmargin],
	qd.[apuk_subscriptionstartdate],
	qd.[apuk_subscriptionenddate],
	qd.[apuk_subscriptionid],
	qd.[apuk_subscriptionnoofmonths],
	qd.[lineitemnumber],
	qd.[quantity],
	qd.[apuk_revenueschedule],
	qd.priceperunit, 
	qd.apuk_voucherid, 
	qd.volumediscountamount_base, 
	qd.volumediscountamount, 
	qd.uomid, 
	qd.msdyn_totalchargesamount, 
	qd.msdyn_taxable, 
	qd.apuk_taxrate, 
	qd.msdyn_startdate, 
	qd.msdyn_shippingwarehouse, 
	qd.msdyn_shippingsite, 
	qd.shipto_postalcode, 
	qd.shipto_line3, 
	qd.shipto_line2, 
	qd.shipto_line1, 
	qd.shipto_stateorprovince, 
	qd.shipto_telephone, 
	qd.shipto_name, 
	qd.shipto_fax, 
	qd.shipto_country, 
	qd.shipto_contactname, 
	qd.shipto_city, 
	qd.willcall, 
	qd.msdyn_pricelist, 
	qd.msdyn_serviceterritory, 
	qd.msdyn_serviceaccount, 
	qd.sequencenumber, 
	qd.isproductoverridden, 
	qd.salesrepid, 
	qd.msdyn_salestaxcode, 
	qd.msdyn_salesquotationstatus, 
	qd.msdyn_salesquotationpromisingmethod, 
	qd.msdyn_salesproductcategory, 
	qd.msdyn_salespricequantity, 
	qd.msdyn_requestedreceiptdate, 
	qd.requestdeliveryby, 
	qd.apuk_regulatedschemeid, 
	qd.overriddencreatedon, 
	qd.propertyconfigurationstatus, 
	qd.msdyn_project, 
	qd.ispriceoverridden, 
	qd.apuk_parentrevisedquoteid, 
	qd.apuk_parentopportunityid, 
	qd.parentbundleidref, 
	qd.parentbundleid, 
	qd.owningbusinessunit, 
	qd.msdyn_opportunityproductid, 
	qd.msdyn_opportunityline, 
	qd.msdyn_multilinediscountpercentage, 
	qd.msdyn_multilinediscountamount, 
	qd.modifiedonbehalfby, 
	qd.msdyn_linetype, 
	qd.msdyn_linediscountpercentage, 
	qd.msdyn_linediscountamount, 
	qd.msdyn_linedescription2, 
	qd.msdyn_isdeliveryaddressspecific, 
	qd.msdyn_isdeliveryaddressprivate, 
	qd.msdyn_invoicefrequency, 
	qd.msdyn_includetime, 
	qd.msdyn_includematerial, 
	qd.msdyn_includeexpense, 
	qd.msdyn_importdetailsfromagreement, 
	qd.shipto_freighttermscode, 
	qd.msdyn_formatteddeliveryaddress, 
	qd.msdyn_fixedpricecharges, 
	qd.msdyn_externalitemnumber, 
	qd.exchangerate, 
	qd.msdyn_enddate, 
	qd.msdyn_duration, 
	qd.apuk_discountapproval, 
	qd.description, 
	qd.msdyn_deliverybuildingcompliment, 
	qd.msdyn_deliveryaddresspostbox, 
	qd.msdyn_deliveryaddressname, 
	qd.msdyn_deliveryaddresslongitude, 
	qd.msdyn_deliveryaddresslocationid, 
	qd.msdyn_deliveryaddresslatitude, 
	qd.msdyn_deliveryaddressdunsnumber, 
	qd.msdyn_deliveryaddressdistrictname, 
	qd.msdyn_deliveryaddressdescription, 
	qd.msdyn_deliveryaddresscountyid, 
	qd.msdyn_budgetamount, 
	qd.createdonbehalfby, 
	qd.msdyn_costamount_base, 
	qd.msdyn_costamount, 
	qd.msdyn_company, 
	qd.productassociationid, 
	qd.msdyn_budgetamount_base, 
	qd.msdyn_billingstartdate, 
	qd.msdyn_billingmethod, 
	qd.msdyn_allowedunderdeliverypercentage, 
	qd.msdyn_allowedoverdeliverypercentage, 
	qd.msdyn_agreement
FROM synapse_ce.quotedetail qd
	LEFT JOIN synapse_ce.transactioncurrency cur
		ON qd.[transactioncurrencyid] = cur.[transactioncurrencyid]
	LEFT JOIN synapse_ce.GlobalOptionSetMetadata prdtypecode
		ON qd.[producttypecode] = prdtypecode.[Option]
		AND prdtypecode.[OptionSetName] = 'producttypecode'
		AND prdtypecode.[EntityName] = 'quotedetail'
	WHERE EXISTS ( --Remove Quote lines from Quotes linked to Test Records
		SELECT quoteid
		FROM synapse_ce.vwQuote Q
		WHERE Q.quoteid = qd.quoteid
		)
